import { Form, usePage } from '@inertiajs/react';
import InputError from '../../components/input-error';
import PasswordInput from '../../components/password-input';
import { Button } from '../../components/ui/button';
import { Input } from '../../components/ui/input';
import { Label } from '../../components/ui/label';
import { Spinner } from '../../components/ui/spinner';
import type { ResetPasswordPageData } from '@splicewire/beam-resources/types/accounts-pages';

// theme-entries-and-authoring STR-03: a sealed island (editor/registry.tsx), no longer the top-level
// Inertia page — read via usePage() instead of received as direct component props.
export default function ResetPassword() {
    const { token, email, passwordRules } =
        usePage<ResetPasswordPageData>().props;
    // Query input is unvalidated on GET; only text belongs in the email form control.
    const emailValue = typeof email === 'string' ? email : '';

    return (
        <>
            <Form
                action="/reset-password"
                method="post"
                transform={(data) => ({ ...data, token, email: emailValue })}
                resetOnSuccess={['password', 'passwordConfirmation']}
            >
                {({ processing, errors }) => (
                    <div className="grid gap-6">
                        <div className="grid gap-2">
                            <Label htmlFor="email">Email</Label>
                            <Input
                                id="email"
                                type="email"
                                name="email"
                                autoComplete="email"
                                value={emailValue}
                                className="mt-1 block w-full"
                                readOnly
                            />
                            <InputError
                                message={errors.email}
                                className="mt-2"
                            />
                        </div>

                        <div className="grid gap-2">
                            <Label htmlFor="password">Password</Label>
                            <PasswordInput
                                id="password"
                                name="password"
                                autoComplete="new-password"
                                className="mt-1 block w-full"
                                autoFocus
                                placeholder="Password"
                                passwordrules={passwordRules}
                            />
                            <InputError message={errors.password} />
                        </div>

                        <div className="grid gap-2">
                            <Label htmlFor="passwordConfirmation">
                                Confirm password
                            </Label>
                            <PasswordInput
                                id="passwordConfirmation"
                                name="passwordConfirmation"
                                autoComplete="new-password"
                                className="mt-1 block w-full"
                                placeholder="Confirm password"
                                passwordrules={passwordRules}
                            />
                            <InputError
                                message={errors.passwordConfirmation}
                                className="mt-2"
                            />
                        </div>

                        <Button
                            type="submit"
                            className="mt-4 w-full"
                            disabled={processing}
                            data-test="reset-password-button"
                        >
                            {processing && <Spinner />}
                            Reset password
                        </Button>
                    </div>
                )}
            </Form>
        </>
    );
}
